def order(api, customer_id, *items):
    return api.orders.handle_create({"customer_id": customer_id,
                                     "items": [{"sku": s, "quantity": q} for s, q in items]})


def test_order_history_unknown_customer_is_404(shop):
    response = shop.insights.handle_order_history("nobody")
    assert response.status == 404
    assert response.body == {"error": "customer not found"}


def test_order_history_for_customer_without_orders_is_empty(shop):
    response = shop.insights.handle_order_history("c1")
    assert response.status == 200
    assert response.body == {"customer_id": "c1", "orders": []}


def test_order_history_is_newest_first_with_cancelled_orders_and_matching_totals(shop):
    big = order(shop, "c2", ("BOOK", 4)).body["order_id"]        # 10_000 subtotal, gold 15% off
    cancelled = order(shop, "c2", ("PEN", 1)).body["order_id"]
    latest = order(shop, "c2", ("LAMP", 1)).body["order_id"]
    shop.orders.handle_cancel(cancelled)

    response = shop.insights.handle_order_history("c2")

    assert response.status == 200
    assert response.body["customer_id"] == "c2"
    assert [o["order_id"] for o in response.body["orders"]] == [latest, cancelled, big]
    assert response.body["orders"][1]["status"] == "cancelled"
    for entry in response.body["orders"]:
        summary = shop.orders.handle_get(entry["order_id"]).body
        assert entry == {"order_id": summary["order_id"], "status": summary["status"],
                         "total_cents": summary["total_cents"]}
    assert response.body["orders"][2]["total_cents"] == 8_500


def test_lifetime_value_unknown_customer_is_404(shop):
    response = shop.insights.handle_lifetime_value("nobody")
    assert response.status == 404
    assert response.body == {"error": "customer not found"}


def test_lifetime_value_for_customer_without_orders_is_zero(shop):
    response = shop.insights.handle_lifetime_value("c1")
    assert response.status == 200
    assert response.body == {"customer_id": "c1", "order_count": 0, "lifetime_value_cents": 0}


def test_lifetime_value_excludes_cancelled_orders_and_includes_discounts(shop):
    order(shop, "c2", ("BOOK", 4))                      # 10_000 subtotal, gold 15% off -> 8_500
    cancelled = order(shop, "c2", ("LAMP", 1)).body["order_id"]   # 6_000, cancelled
    order(shop, "c2", ("PEN", 1))                       # 300
    shop.orders.handle_cancel(cancelled)

    response = shop.insights.handle_lifetime_value("c2")

    assert response.status == 200
    assert response.body == {"customer_id": "c2", "order_count": 2, "lifetime_value_cents": 8_800}


def test_top_customers_rejects_invalid_limit(shop):
    for bad in (0, -1, True, False, "3", None, 1.5):
        response = shop.insights.handle_top_customers(bad)
        assert response.status == 400, bad
        assert "limit" in response.body["error"]


def test_top_customers_ranks_by_lifetime_value_and_skips_zero(shop):
    shop.customers.handle_register({"customer_id": "c0", "name": "Zed", "email": "z@example.com"})
    shop.customers.handle_register({"customer_id": "c3", "name": "Linus", "email": "l@example.com"})
    order(shop, "c2", ("BOOK", 4))                      # 8_500 (gold)
    order(shop, "c1", ("BOOK", 4))                      # 10_000 subtotal, standard 10% off -> 9_000
